-- 091_payment_schedule.sql
-- Roadmap G.36: contract-derived payment schedule; no money movement.
CREATE TABLE IF NOT EXISTS public.project_payment_schedules(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,award_id uuid NOT NULL REFERENCES public.project_tender_awards(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),mode text NOT NULL CHECK(mode IN('MILESTONE','MEASURED_BOQ')),status text NOT NULL CHECK(status IN('DRAFT','ACTIVE','SUPERSEDED')),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),contract_value numeric(24,2)NOT NULL CHECK(contract_value>=0),scheduled_percentage numeric(8,4)NOT NULL CHECK(scheduled_percentage>=0 AND scheduled_percentage<=100),scheduled_amount numeric(24,2)NOT NULL CHECK(scheduled_amount>=0),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),activated_by uuid REFERENCES auth.users(id)ON DELETE RESTRICT,activated_at timestamptz,UNIQUE(project_id,version_number),UNIQUE(id,project_id)
);
CREATE UNIQUE INDEX project_payment_schedule_one_draft_idx ON public.project_payment_schedules(project_id)WHERE status='DRAFT';CREATE UNIQUE INDEX project_payment_schedule_one_active_idx ON public.project_payment_schedules(project_id)WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS public.project_payment_milestones(
 id uuid PRIMARY KEY,payment_schedule_id uuid NOT NULL,project_id bigint NOT NULL,sequence_number integer NOT NULL CHECK(sequence_number>0),title text NOT NULL CHECK(btrim(title)<>''AND char_length(title)<=200),planned_date date NOT NULL,percentage numeric(8,4)NOT NULL CHECK(percentage>0 AND percentage<=100),planned_amount numeric(24,2)NOT NULL CHECK(planned_amount>=0),condition text NOT NULL CHECK(btrim(condition)<>''AND char_length(condition)<=2000),status text NOT NULL DEFAULT'UPCOMING'CHECK(status IN('UPCOMING','READY_FOR_REVIEW','UNDER_CERTIFICATION','APPROVED','SENT_FOR_PAYMENT','PAID')),UNIQUE(payment_schedule_id,sequence_number),FOREIGN KEY(payment_schedule_id,project_id)REFERENCES public.project_payment_schedules(id,project_id)ON DELETE RESTRICT
);
ALTER TABLE public.project_payment_schedules ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_payment_milestones ENABLE ROW LEVEL SECURITY;
CREATE POLICY payment_schedules_select ON public.project_payment_schedules FOR SELECT TO authenticated USING(public.can_access_project(project_id));CREATE POLICY payment_milestones_select ON public.project_payment_milestones FOR SELECT TO authenticated USING(public.can_access_project(project_id));
REVOKE ALL ON TABLE public.project_payment_schedules,public.project_payment_milestones FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_payment_schedules,public.project_payment_milestones TO authenticated;

CREATE OR REPLACE FUNCTION public.get_project_payment_schedule(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE u uuid:=auth.uid();role text;a public.project_tender_awards%ROWTYPE;s public.project_payment_schedules%ROWTYPE;BEGIN SELECT upper(role)INTO role FROM public.profiles WHERE id=u;IF u IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT *INTO a FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1;SELECT *INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id ORDER BY(status='DRAFT')DESC,version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'role',role,'canManage',role IN('PM','ADMIN')AND public.can_write_project(p_project_id),'hasAward',a.id IS NOT NULL,'award',CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object('awardId',a.id,'contractorName',a.contractor_name,'currencyCode',a.currency_code,'contractValue',a.contract_value)END,'schedule',CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object('paymentScheduleId',s.id,'versionNumber',s.version_number,'mode',s.mode,'status',s.status,'currencyCode',s.currency_code,'contractValue',s.contract_value,'scheduledPercentage',s.scheduled_percentage,'scheduledAmount',s.scheduled_amount,'unallocatedPercentage',100-s.scheduled_percentage,'milestones',COALESCE((SELECT jsonb_agg(jsonb_build_object('milestoneId',m.id,'sequenceNumber',m.sequence_number,'title',m.title,'plannedDate',m.planned_date,'percentage',m.percentage,'plannedAmount',m.planned_amount,'condition',m.condition,'status',m.status)ORDER BY m.sequence_number)FROM public.project_payment_milestones m WHERE m.payment_schedule_id=s.id),'[]'::jsonb))END);END;$$;

CREATE OR REPLACE FUNCTION public.save_project_payment_schedule(p_project_id bigint,p_schedule_id uuid,p_mode text,p_milestones jsonb,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role text;a public.project_tender_awards%ROWTYPE;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;total_pct numeric;total_amount numeric;next_version integer;result jsonb;x jsonb;ids uuid[]:='{}';BEGIN SELECT upper(role)INTO role FROM public.profiles WHERE id=u;IF u IS NULL OR role NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_schedule_id IS NULL OR p_client_request_id IS NULL OR p_mode NOT IN('MILESTONE','MEASURED_BOQ')OR jsonb_typeof(p_milestones)<>'array'OR jsonb_array_length(p_milestones)=0 THEN RAISE EXCEPTION'INVALID_PAYMENT_SCHEDULE_COMMAND'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_schedule.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_schedule.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;PERFORM pg_advisory_xact_lock(p_project_id);SELECT *INTO a FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1;IF a.id IS NULL THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_REQUIRES_AWARD'USING ERRCODE='55000';END IF;SELECT *INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id AND status='DRAFT'FOR UPDATE;IF s.id IS NOT NULL AND s.id<>p_schedule_id THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_DRAFT_ID_CONFLICT'USING ERRCODE='23505';END IF;FOR x IN SELECT value FROM jsonb_array_elements(p_milestones)LOOP IF (x->>'milestoneId')IS NULL OR(x->>'percentage')::numeric<=0 OR btrim(COALESCE(x->>'title',''))=''OR btrim(COALESCE(x->>'condition',''))=''OR(x->>'plannedDate')::date IS NULL OR(x->>'milestoneId')::uuid=ANY(ids)THEN RAISE EXCEPTION'INVALID_PAYMENT_MILESTONE'USING ERRCODE='22023';END IF;ids:=array_append(ids,(x->>'milestoneId')::uuid);END LOOP;SELECT sum((value->>'percentage')::numeric)INTO total_pct FROM jsonb_array_elements(p_milestones);IF total_pct>100 THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_PERCENT_EXCEEDS_100'USING ERRCODE='23514';END IF;total_amount:=round(a.contract_value*total_pct/100,2);
IF s.id IS NULL THEN SELECT COALESCE(max(version_number),0)+1 INTO next_version FROM public.project_payment_schedules WHERE project_id=p_project_id;INSERT INTO public.project_payment_schedules VALUES(p_schedule_id,p_project_id,a.id,next_version,p_mode,'DRAFT',a.currency_code,a.contract_value,total_pct,total_amount,u,now(),NULL,NULL);ELSE DELETE FROM public.project_payment_milestones WHERE payment_schedule_id=s.id;UPDATE public.project_payment_schedules SET mode=p_mode,scheduled_percentage=total_pct,scheduled_amount=total_amount WHERE id=s.id;END IF;INSERT INTO public.project_payment_milestones(id,payment_schedule_id,project_id,sequence_number,title,planned_date,percentage,planned_amount,condition)SELECT(value->>'milestoneId')::uuid,p_schedule_id,p_project_id,row_number()OVER(),btrim(value->>'title'),(value->>'plannedDate')::date,(value->>'percentage')::numeric,round(a.contract_value*(value->>'percentage')::numeric/100,2),btrim(value->>'condition')FROM jsonb_array_elements(p_milestones);result:=jsonb_build_object('paymentScheduleId',p_schedule_id,'scheduledPercentage',total_pct,'scheduledAmount',total_amount,'unallocatedPercentage',100-total_pct,'milestoneCount',jsonb_array_length(p_milestones));UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;

CREATE OR REPLACE FUNCTION public.activate_project_payment_schedule(p_schedule_id uuid,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role text;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;result jsonb;BEGIN SELECT *INTO s FROM public.project_payment_schedules WHERE id=p_schedule_id FOR UPDATE;SELECT upper(role)INTO role FROM public.profiles WHERE id=u;IF s.id IS NULL THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_NOT_FOUND'USING ERRCODE='P0002';END IF;IF u IS NULL OR role NOT IN('PM','ADMIN')OR public.can_write_project(s.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_FORBIDDEN'USING ERRCODE='42501';END IF;IF s.status<>'DRAFT'OR p_client_request_id IS NULL THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_NOT_DRAFT'USING ERRCODE='55000';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_schedule.activate',p_client_request_id,s.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_schedule.activate'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;UPDATE public.project_payment_schedules SET status='SUPERSEDED'WHERE project_id=s.project_id AND status='ACTIVE';UPDATE public.project_payment_schedules SET status='ACTIVE',activated_by=u,activated_at=now()WHERE id=s.id;result:=jsonb_build_object('paymentScheduleId',s.id,'status','ACTIVE','scheduledPercentage',s.scheduled_percentage,'unallocatedPercentage',100-s.scheduled_percentage);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
REVOKE ALL ON FUNCTION public.get_project_payment_schedule(bigint),public.save_project_payment_schedule(bigint,uuid,text,jsonb,uuid),public.activate_project_payment_schedule(uuid,uuid)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_project_payment_schedule(bigint),public.save_project_payment_schedule(bigint,uuid,text,jsonb,uuid),public.activate_project_payment_schedule(uuid,uuid)TO authenticated;

-- Compile-safe replacements: profile.role is qualified and never conflicts with a PL/pgSQL variable.
CREATE OR REPLACE FUNCTION public.get_project_payment_schedule(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;a public.project_tender_awards%ROWTYPE;s public.project_payment_schedules%ROWTYPE;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;IF u IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT *INTO a FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1;SELECT *INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id ORDER BY(status='DRAFT')DESC,version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'role',v_role,'canManage',v_role IN('PM','ADMIN')AND public.can_write_project(p_project_id),'hasAward',a.id IS NOT NULL,'award',CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object('awardId',a.id,'contractorName',a.contractor_name,'currencyCode',a.currency_code,'contractValue',a.contract_value)END,'schedule',CASE WHEN s.id IS NULL THEN NULL ELSE jsonb_build_object('paymentScheduleId',s.id,'versionNumber',s.version_number,'mode',s.mode,'status',s.status,'currencyCode',s.currency_code,'contractValue',s.contract_value,'scheduledPercentage',s.scheduled_percentage,'scheduledAmount',s.scheduled_amount,'unallocatedPercentage',100-s.scheduled_percentage,'milestones',COALESCE((SELECT jsonb_agg(jsonb_build_object('milestoneId',m.id,'sequenceNumber',m.sequence_number,'title',m.title,'plannedDate',m.planned_date,'percentage',m.percentage,'plannedAmount',m.planned_amount,'condition',m.condition,'status',m.status)ORDER BY m.sequence_number)FROM public.project_payment_milestones m WHERE m.payment_schedule_id=s.id),'[]'::jsonb))END);END;$$;

CREATE OR REPLACE FUNCTION public.save_project_payment_schedule(p_project_id bigint,p_schedule_id uuid,p_mode text,p_milestones jsonb,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;a public.project_tender_awards%ROWTYPE;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;total_pct numeric;total_amount numeric;next_version integer;result jsonb;x jsonb;ids uuid[]:='{}';
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_schedule_id IS NULL OR p_client_request_id IS NULL OR p_mode NOT IN('MILESTONE','MEASURED_BOQ')OR jsonb_typeof(p_milestones)<>'array'OR jsonb_array_length(p_milestones)=0 THEN RAISE EXCEPTION'INVALID_PAYMENT_SCHEDULE_COMMAND'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_schedule.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_schedule.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;PERFORM pg_advisory_xact_lock(p_project_id);SELECT *INTO a FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1;IF a.id IS NULL THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_REQUIRES_AWARD'USING ERRCODE='55000';END IF;SELECT *INTO s FROM public.project_payment_schedules WHERE project_id=p_project_id AND status='DRAFT'FOR UPDATE;IF s.id IS NOT NULL AND s.id<>p_schedule_id THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_DRAFT_ID_CONFLICT'USING ERRCODE='23505';END IF;FOR x IN SELECT value FROM jsonb_array_elements(p_milestones)LOOP IF (x->>'milestoneId')IS NULL OR COALESCE((x->>'percentage')::numeric,0)<=0 OR btrim(COALESCE(x->>'title',''))=''OR btrim(COALESCE(x->>'condition',''))=''OR(x->>'plannedDate')IS NULL OR(x->>'milestoneId')::uuid=ANY(ids)THEN RAISE EXCEPTION'INVALID_PAYMENT_MILESTONE'USING ERRCODE='22023';END IF;ids:=array_append(ids,(x->>'milestoneId')::uuid);END LOOP;SELECT sum((value->>'percentage')::numeric)INTO total_pct FROM jsonb_array_elements(p_milestones);IF total_pct>100 THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_PERCENT_EXCEEDS_100'USING ERRCODE='23514';END IF;total_amount:=round(a.contract_value*total_pct/100,2);IF s.id IS NULL THEN SELECT COALESCE(max(version_number),0)+1 INTO next_version FROM public.project_payment_schedules WHERE project_id=p_project_id;INSERT INTO public.project_payment_schedules VALUES(p_schedule_id,p_project_id,a.id,next_version,p_mode,'DRAFT',a.currency_code,a.contract_value,total_pct,total_amount,u,now(),NULL,NULL);ELSE DELETE FROM public.project_payment_milestones WHERE payment_schedule_id=s.id;UPDATE public.project_payment_schedules SET mode=p_mode,scheduled_percentage=total_pct,scheduled_amount=total_amount WHERE id=s.id;END IF;INSERT INTO public.project_payment_milestones(id,payment_schedule_id,project_id,sequence_number,title,planned_date,percentage,planned_amount,condition)SELECT(value->>'milestoneId')::uuid,p_schedule_id,p_project_id,ordinality,btrim(value->>'title'),(value->>'plannedDate')::date,(value->>'percentage')::numeric,round(a.contract_value*(value->>'percentage')::numeric/100,2),btrim(value->>'condition')FROM jsonb_array_elements(p_milestones)WITH ORDINALITY AS e(value,ordinality);result:=jsonb_build_object('paymentScheduleId',p_schedule_id,'scheduledPercentage',total_pct,'scheduledAmount',total_amount,'unallocatedPercentage',100-total_pct,'milestoneCount',jsonb_array_length(p_milestones));UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;

CREATE OR REPLACE FUNCTION public.activate_project_payment_schedule(p_schedule_id uuid,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;result jsonb;
BEGIN SELECT *INTO s FROM public.project_payment_schedules WHERE id=p_schedule_id FOR UPDATE;SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;IF s.id IS NULL THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_NOT_FOUND'USING ERRCODE='P0002';END IF;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(s.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_FORBIDDEN'USING ERRCODE='42501';END IF;IF s.status<>'DRAFT'OR p_client_request_id IS NULL THEN RAISE EXCEPTION'PAYMENT_SCHEDULE_NOT_DRAFT'USING ERRCODE='55000';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_schedule.activate',p_client_request_id,s.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_schedule.activate'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;UPDATE public.project_payment_schedules SET status='SUPERSEDED'WHERE project_id=s.project_id AND status='ACTIVE';UPDATE public.project_payment_schedules SET status='ACTIVE',activated_by=u,activated_at=now()WHERE id=s.id;result:=jsonb_build_object('paymentScheduleId',s.id,'status','ACTIVE','scheduledPercentage',s.scheduled_percentage,'unallocatedPercentage',100-s.scheduled_percentage);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
